import { ref, onMounted } from 'vue'
import { gsap } from 'gsap'

const emit = defineEmits<{ scrollTo: [index: number] }>()
const contentRef = ref<HTMLElement | null>(null)

onMounted(() => {
  if (contentRef.value) {
    gsap.fromTo(
      contentRef.value.children,
      { opacity: 0, y: 32 },
      {
        opacity: 1,
        y: 0,
        stagger: 0.12,
        duration: 1.1,
        ease: 'power3.out',
        delay: 0.3,
