let timer: ReturnType<typeof setInterval>

onMounted(() => {
  // Ganti gambar setiap 3 detik (3000 ms)
  timer = setInterval(() => {
    currentImageIndex.value = (currentImageIndex.value + 1) % images.length
  }, 3000)
})

